-- C10 / P10.8 — social isolation, recoverable provider loss, and paid-action fail-closed evidence.
create table if not exists public.command_center_social_account_isolation_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 isolation_event_id text not null check(btrim(isolation_event_id)<>''), entity_id text not null check(btrim(entity_id)<>''), company_id text, brand_id text not null check(btrim(brand_id)<>''), project_id text,
 account_id text not null check(btrim(account_id)<>''), platform_identity_id text not null check(btrim(platform_identity_id)<>''), credential_ref text, evidence_refs text[] not null check(cardinality(evidence_refs)>0), observed_at timestamptz not null,
 primary key(owner_id,isolation_event_id), unique(owner_id,account_id,observed_at), unique(owner_id,platform_identity_id,observed_at), check(company_id is null or btrim(company_id)<>''), check(project_id is null or btrim(project_id)<>''), check(credential_ref is null or btrim(credential_ref)<>'')
);
create table if not exists public.command_center_social_recovery_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 recovery_event_id text not null check(btrim(recovery_event_id)<>''), recovery_case_id text not null check(btrim(recovery_case_id)<>''), brand_id text not null check(btrim(brand_id)<>''), account_id text not null check(btrim(account_id)<>''),
 kind text not null check(kind in ('connection_loss','credential_rotation','provider_outage','identity_conflict','scope_loss')), status text not null check(status in ('open','needs_owner','reconciling','recovered','blocked')), provider_state text not null check(provider_state in ('connected','disconnected','expired','revoked','unavailable')),
 missing_scopes text[] not null default '{}'::text[], owner_action_ref text, reconnect_ref text, observed_at timestamptz not null, evidence_refs text[] not null check(cardinality(evidence_refs)>0),
 secrets_exposed boolean not null default false check(secrets_exposed=false), protected_action_authorized boolean not null default false check(protected_action_authorized=false),
 primary key(owner_id,recovery_event_id), unique(owner_id,recovery_case_id,observed_at), check(owner_action_ref is null or btrim(owner_action_ref)<>''), check(reconnect_ref is null or btrim(reconnect_ref)<>'')
);
create table if not exists public.command_center_social_paid_action_assessment_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 assessment_event_id text not null check(btrim(assessment_event_id)<>''), action_id text not null check(btrim(action_id)<>''), brand_id text not null check(btrim(brand_id)<>''), account_id text not null check(btrim(account_id)<>''), action_kind text not null check(btrim(action_kind)<>''), amount numeric not null check(amount>=0), currency text not null check(btrim(currency)<>''), provider_state text not null check(provider_state in ('connected','disconnected','expired','revoked','unavailable')),
 allowed boolean not null, reason text not null check(reason in ('authorized','missing_exact_authorization','authorization_mismatch','authorization_expired','provider_not_connected','amount_exceeds_authorization')), authorization_ref text, observed_at timestamptz not null, evidence_refs text[] not null check(cardinality(evidence_refs)>0),
 primary key(owner_id,assessment_event_id), unique(owner_id,action_id,observed_at), check((allowed=true and reason='authorized' and authorization_ref is not null and btrim(authorization_ref)<>'') or allowed=false)
);
create or replace function public.command_center_reject_social_recovery_assessment_mutation() returns trigger language plpgsql set search_path to 'public' as $$ begin raise exception 'Social recovery assessment evidence is immutable'; end $$;
drop trigger if exists command_center_social_isolation_history_immutable on public.command_center_social_account_isolation_history; create trigger command_center_social_isolation_history_immutable before update or delete on public.command_center_social_account_isolation_history for each row execute function public.command_center_reject_social_recovery_assessment_mutation();
drop trigger if exists command_center_social_recovery_history_immutable on public.command_center_social_recovery_history; create trigger command_center_social_recovery_history_immutable before update or delete on public.command_center_social_recovery_history for each row execute function public.command_center_reject_social_recovery_assessment_mutation();
drop trigger if exists command_center_social_paid_assessment_immutable on public.command_center_social_paid_action_assessment_history; create trigger command_center_social_paid_assessment_immutable before update or delete on public.command_center_social_paid_action_assessment_history for each row execute function public.command_center_reject_social_recovery_assessment_mutation();
alter table public.command_center_social_account_isolation_history enable row level security; alter table public.command_center_social_recovery_history enable row level security; alter table public.command_center_social_paid_action_assessment_history enable row level security;
revoke all on table public.command_center_social_account_isolation_history,public.command_center_social_recovery_history,public.command_center_social_paid_action_assessment_history from public,anon,authenticated;
grant select,insert on table public.command_center_social_account_isolation_history,public.command_center_social_recovery_history,public.command_center_social_paid_action_assessment_history to authenticated;
create policy p10_8_social_isolation_owner on public.command_center_social_account_isolation_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
create policy p10_8_social_recovery_owner on public.command_center_social_recovery_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()) and secrets_exposed=false and protected_action_authorized=false);
create policy p10_8_social_paid_assessment_owner on public.command_center_social_paid_action_assessment_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
